import narwhals as nw
import pandas as pd
import polars as pl


@nw.dataframe_namespace
def add_total(df):
    """Add a 'total' column equal to price * quantity."""
    return df.with_columns(
        total=nw.col("price") * nw.col("quantity")
    )


# Test with pandas
pdf = pd.DataFrame({
    "price": [10, 20, 30],
    "quantity": [2, 3, 1]
})
print("Pandas result:")
print(add_total(pdf))

# Test with polars
plf = pl.DataFrame({
    "price": [10, 20, 30],
    "quantity": [2, 3, 1]
})
print("\nPolars result:")
print(add_total(plf))
